window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["vercel"]={html:"<div class=\"own-vercel\">\n  <a class=\"vc-skip\" href=\"#vcMain\">Skip to content</a>\n\n  <!-- ── NAV ─────────────────────────────────────────────────────────── -->\n  <header class=\"vc-nav\" id=\"vcNav\">\n    <div class=\"vc-nav-in\">\n      <a class=\"vc-brand\" href=\"#vcMain\" aria-label=\"Northwind home\">\n        <span class=\"vc-brand-mark\" aria-hidden=\"true\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M12 3 22 20H2z\" fill=\"#171717\"/></svg>\n        </span>\n        <span class=\"vc-brand-name\">Northwind</span>\n      </a>\n      <nav class=\"vc-nav-links\" aria-label=\"Primary\">\n        <a href=\"#vcProduct\">Product</a>\n        <a href=\"#vcMesh\">Platform</a>\n        <a href=\"#vcTemplates\">Templates</a>\n        <a href=\"#vcPricing\">Pricing</a>\n        <a href=\"#vcDocs\">Docs</a>\n      </nav>\n      <div class=\"vc-nav-actions\">\n        <a class=\"vc-cta vc-cta-ghost\" href=\"#\">Ask AI</a>\n        <a class=\"vc-cta vc-cta-login\" href=\"#\">Log in</a>\n        <a class=\"vc-cta vc-cta-signup\" href=\"#vcPricing\">Sign up</a>\n        <button class=\"vc-burger\" type=\"button\" aria-label=\"Menu\" data-vc-menu aria-expanded=\"false\">\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 7h16M4 12h16M4 17h16\"/></svg>\n        </button>\n      </div>\n    </div>\n    <div class=\"vc-drawer\" hidden data-vc-drawer>\n      <a href=\"#vcProduct\">Product</a><a href=\"#vcMesh\">Platform</a><a href=\"#vcTemplates\">Templates</a>\n      <a href=\"#vcPricing\">Pricing</a><a href=\"#vcDocs\">Docs</a>\n    </div>\n  </header>\n\n  <main id=\"vcMain\">\n    <!-- ── HERO — mesh gradient ───────────────────────────────────────── -->\n    <section class=\"vc-hero\">\n      <div class=\"vc-mesh\" aria-hidden=\"true\">\n        <span class=\"vc-blob vc-blob-a\"></span>\n        <span class=\"vc-blob vc-blob-b\"></span>\n        <span class=\"vc-blob vc-blob-c\"></span>\n      </div>\n      <div class=\"vc-wrap vc-hero-in\">\n        <p class=\"vc-mono-badge\">Northwind · operations analytics</p>\n        <h1 class=\"vc-display-xl\">Build and deploy on the operations cloud.</h1>\n        <p class=\"vc-lead\">Northwind gives ops teams the fastest path from raw shipment data to a live dashboard. Push a metric, watch it render, ship the report — in seconds.</p>\n        <div class=\"vc-hero-cta\">\n          <a class=\"vc-btn vc-btn-primary\" href=\"#vcPricing\">Start deploying</a>\n          <a class=\"vc-btn vc-btn-secondary\" href=\"#vcDocs\">Read the docs</a>\n        </div>\n        <p class=\"vc-hero-note\">Free for 3 seats · No credit card · SOC 2 Type II</p>\n      </div>\n      <div class=\"vc-strip-wrap\">\n        <p class=\"vc-strip-cap\">Trusted by operations teams at</p>\n        <div class=\"vc-strip\">\n          <span>Vector Freight</span><span>Halden Retail</span><span>Miro Labs</span><span>Aperture Foods</span><span>Kestrel Bank</span>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── THREE FEATURES — mesh band ─────────────────────────────────── -->\n    <section class=\"vc-band vc-band-mesh\" id=\"vcProduct\">\n      <div class=\"vc-wrap\">\n        <p class=\"vc-eyebrow\">Deploy your first dashboard in seconds</p>\n        <h2 class=\"vc-display-lg\">A compute model for all workloads.</h2>\n        <div class=\"vc-feature3\" id=\"vcFeature3\"></div>\n      </div>\n    </section>\n\n    <!-- ── SHOWCASE LIGHT — code editor mockup ────────────────────────── -->\n    <section class=\"vc-band vc-band-soft\" id=\"vcDocs\">\n      <div class=\"vc-wrap vc-show-in\">\n        <div class=\"vc-show-copy\">\n          <p class=\"vc-eyebrow\">Developer first</p>\n          <h2 class=\"vc-display-lg\">Your ops pipeline, delivered.</h2>\n          <p class=\"vc-body\">Northwind is a deployment target for your data, not a black box. Query it from code, version your dashboards, and roll back any board like a commit.</p>\n          <a class=\"vc-link\" href=\"#\">Explore the SDK <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12h14M13 6l6 6-6 6\"/></svg></a>\n        </div>\n        <div class=\"vc-editor\" aria-label=\"Northwind code editor\">\n          <div class=\"vc-editor-top\"><span class=\"vc-edot\"></span><span class=\"vc-edot\"></span><span class=\"vc-edot\"></span><span class=\"vc-editor-file\">northwind.config.ts</span></div>\n          <pre class=\"vc-editor-body\"><code><span class=\"vc-c-kw\">import</span> { defineDashboard } <span class=\"vc-c-kw\">from</span> <span class=\"vc-c-str\">'@northwind/core'</span>\n\n<span class=\"vc-c-kw\">export default</span> defineDashboard({\n  region: <span class=\"vc-c-str\">'metro-manila'</span>,\n  panels: [<span class=\"vc-c-str\">'throughput'</span>, <span class=\"vc-c-str\">'revenue'</span>],\n  refresh: <span class=\"vc-c-num\">60</span>\n})</code></pre>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── TEMPLATE GRID ──────────────────────────────────────────────── -->\n    <section class=\"vc-band\" id=\"vcTemplates\">\n      <div class=\"vc-wrap\">\n        <div class=\"vc-sec-head\">\n          <p class=\"vc-eyebrow\">Templates</p>\n          <h2 class=\"vc-display-lg\">Deploy your first board</h2>\n        </div>\n        <div class=\"vc-tpl-grid\" id=\"vcTplGrid\"></div>\n      </div>\n    </section>\n\n    <!-- ── DARK BAND — compute ────────────────────────────────────────── -->\n    <section class=\"vc-band vc-band-dark\" id=\"vcMesh\">\n      <div class=\"vc-wrap vc-dark-in\">\n        <div class=\"vc-dark-copy\">\n          <h2 class=\"vc-display-lg\">Every workload, one ledger.</h2>\n          <p class=\"vc-body-on-dark\">From a single region's throughput to a global revenue forecast, Northwind runs the full range of operations compute on the same platform.</p>\n        </div>\n        <div class=\"vc-stats\" id=\"vcStats\"></div>\n      </div>\n    </section>\n\n    <!-- ── PRICING ────────────────────────────────────────────────────── -->\n    <section class=\"vc-band vc-band-soft\" id=\"vcPricing\">\n      <div class=\"vc-wrap\">\n        <div class=\"vc-sec-head vc-sec-center\">\n          <p class=\"vc-eyebrow\">Pricing</p>\n          <h2 class=\"vc-display-lg\">Usage-based, from the first event.</h2>\n        </div>\n        <div class=\"vc-pricing\" id=\"vcPricingGrid\"></div>\n      </div>\n    </section>\n  </main>\n\n  <!-- ── FOOTER ───────────────────────────────────────────────────────── -->\n  <footer class=\"vc-foot\">\n    <div class=\"vc-wrap\">\n      <div class=\"vc-foot-grid\">\n        <div><p class=\"vc-foot-head\">Product</p><a href=\"#vcProduct\">Platform</a><a href=\"#vcTemplates\">Templates</a><a href=\"#vcPricing\">Pricing</a></div>\n        <div><p class=\"vc-foot-head\">Resources</p><a href=\"#vcDocs\">Docs</a><a href=\"#\">Guides</a><a href=\"#\">Changelog</a></div>\n        <div><p class=\"vc-foot-head\">Company</p><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Blog</a></div>\n        <div><p class=\"vc-foot-head\">Legal</p><a href=\"#\">Privacy</a><a href=\"#\">Terms</a></div>\n      </div>\n      <div class=\"vc-foot-bottom\">\n        <span class=\"vc-foot-brand\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" aria-hidden=\"true\"><path d=\"M12 3 22 20H2z\" fill=\"currentColor\"/></svg> Northwind</span>\n        <span>© 2026 · Sample data — showcase only</span>\n      </div>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ VERCEL — Northwind operations analytics, built in Vercel's real page grammar ══\n   Near-white canvas ladder, ink-near-black primary, multi-color mesh gradient as the\n   whole decoration system, Geist + Geist Mono, 100px pill CTAs, stacked shadows.\n   Scoped under `.own-vercel`. */\n\n.own-vercel {\n  --primary: #171717;\n  --on-primary: #ffffff;\n  --ink: #171717;\n  --body: #4d4d4d;\n  --mute: #888888;\n  --hairline: #ebebeb;\n  --hairline-strong: #a1a1a1;\n  --canvas: #ffffff;\n  --canvas-soft: #fafafa;\n  --canvas-soft-2: #f5f5f5;\n  --link: #0070f3;\n\n  --f-sans: 'Geist', 'Inter', system-ui, -apple-system, sans-serif;\n  --f-mono: 'Geist Mono', ui-monospace, 'JetBrains Mono', 'SFMono-Regular', Menlo, monospace;\n\n  --r-xs: 4px;\n  --r-sm: 6px;\n  --r-md: 8px;\n  --r-lg: 12px;\n  --r-xl: 16px;\n  --r-pill: 100px;\n  --gut: clamp(16px, 4.6cqi, 24px);\n  --sec: clamp(48px, 8cqi, 96px);\n\n  --shadow-2: 0px 1px 1px #00000005, 0px 2px 2px #0000000a, 0 0 0 1px #00000014;\n  --shadow-4: 0px 2px 2px #0000000a, 0px 8px 16px -4px #0000000a, 0 0 0 1px #00000014;\n  --shadow-5: 0px 1px 1px #00000005, 0px 8px 16px -4px #0000000a, 0px 24px 32px -8px #0000000f, 0 0 0 1px #00000014;\n\n  position: relative;\n  background: var(--canvas-soft);\n  color: var(--ink);\n  font-family: var(--f-sans);\n  font-size: 16px;\n  line-height: 1.5;\n  text-align: left;\n  overflow-x: clip;\n  -webkit-font-smoothing: antialiased;\n}\n\n.own-vercel *, .own-vercel *::before, .own-vercel *::after { box-sizing: border-box; }\n.own-vercel p { margin: 0; }\n.own-vercel h1, .own-vercel h2, .own-vercel h3 { margin: 0; }\n.own-vercel a { color: inherit; text-decoration: none; }\n.own-vercel img, .own-vercel svg { display: block; }\n.own-vercel button { font: inherit; }\n.own-vercel :focus-visible { outline: 2px solid var(--link); outline-offset: 2px; border-radius: 4px; }\n.own-vercel .vc-band-dark :focus-visible, .own-vercel .vc-foot :focus-visible { outline-color: #fff; }\n\n.own-vercel .vc-wrap { width: 100%; max-width: 1400px; margin: 0 auto; padding: 0 var(--gut); }\n\n.own-vercel .vc-skip {\n  position: absolute; left: 12px; top: -60px; z-index: 60;\n  padding: 10px 16px; border-radius: var(--r-sm); background: var(--ink); color: var(--on-primary);\n  font-weight: 500; transition: top .2s;\n}\n.own-vercel .vc-skip:focus { top: 12px; }\n\n/* ── type — sentence-case, aggressive negative tracking ──────────────── */\n.own-vercel .vc-display-xl { font-size: clamp(32px, 5.4cqi, 48px); font-weight: 600; line-height: 1.05; letter-spacing: -2.4px; }\n.own-vercel .vc-display-lg { font-size: clamp(26px, 3.6cqi, 32px); font-weight: 600; line-height: 1.25; letter-spacing: -1.28px; }\n.own-vercel .vc-display-md { font-size: 24px; font-weight: 600; line-height: 1.33; letter-spacing: -.96px; }\n.own-vercel .vc-lead { font-size: clamp(16px, 1.4cqi, 18px); line-height: 1.55; color: var(--body); }\n.own-vercel .vc-body { font-size: 16px; line-height: 1.5; color: var(--body); }\n.own-vercel .vc-body-on-dark { font-size: 16px; line-height: 1.5; color: rgba(255,255,255,.72); }\n.own-vercel .vc-eyebrow { font-family: var(--f-mono); font-size: 12px; letter-spacing: .02em; text-transform: uppercase; color: var(--mute); margin-bottom: 14px; }\n.own-vercel .vc-mono-badge {\n  display: inline-block; font-family: var(--f-mono); font-size: 12px; color: var(--ink);\n  background: var(--canvas); padding: 4px 10px; border-radius: 9999px;\n  box-shadow: 0 0 0 1px var(--hairline); margin-bottom: 22px;\n}\n.own-vercel .vc-sec-head { max-width: 720px; margin-bottom: clamp(24px, 4cqi, 40px); }\n.own-vercel .vc-sec-center { margin-left: auto; margin-right: auto; text-align: center; }\n\n/* ── buttons ─────────────────────────────────────────────────────────── */\n.own-vercel .vc-btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  height: 48px; padding: 0 12px; border-radius: var(--r-pill);\n  font-size: 16px; font-weight: 500; line-height: 1; white-space: nowrap;\n  transition: background-color .15s, transform .15s, opacity .15s;\n}\n.own-vercel .vc-btn-primary { background: var(--primary); color: var(--on-primary); }\n.own-vercel .vc-btn-primary:hover { opacity: .85; }\n.own-vercel .vc-btn-primary:active { transform: scale(.98); }\n.own-vercel .vc-btn-secondary { background: var(--canvas); color: var(--ink); box-shadow: 0 0 0 1px var(--hairline); }\n.own-vercel .vc-btn-secondary:hover { background: var(--canvas-soft-2); }\n\n/* ── nav ─────────────────────────────────────────────────────────────── */\n.own-vercel .vc-nav { position: sticky; top: 68px; z-index: 40; background: rgba(255,255,255,.85); backdrop-filter: saturate(180%) blur(10px); border-bottom: 1px solid var(--hairline); }\n.own-vercel .vc-nav-in { display: flex; align-items: center; gap: 20px; height: 64px; max-width: 1400px; margin: 0 auto; padding: 12px var(--gut); }\n.own-vercel .vc-brand { display: flex; align-items: center; gap: 8px; flex: none; }\n.own-vercel .vc-brand-mark { width: 22px; height: 22px; }\n.own-vercel .vc-brand-name { font-size: 16px; font-weight: 600; letter-spacing: -.4px; }\n.own-vercel .vc-nav-links { display: flex; gap: 2px; flex: 1 1 auto; }\n.own-vercel .vc-nav-links a { font-size: 14px; font-weight: 500; letter-spacing: -.28px; color: var(--body); padding: 8px 12px; border-radius: 9999px; }\n.own-vercel .vc-nav-links a:hover { color: var(--ink); background: var(--canvas-soft-2); }\n.own-vercel .vc-nav-actions { display: flex; align-items: center; gap: 8px; margin-left: auto; }\n.own-vercel .vc-cta {\n  display: inline-flex; align-items: center; height: 28px; padding: 0 10px; border-radius: var(--r-sm);\n  font-size: 14px; font-weight: 500; letter-spacing: -.28px;\n}\n.own-vercel .vc-cta-ghost { background: var(--canvas); color: var(--ink); box-shadow: 0 0 0 1px var(--hairline); }\n.own-vercel .vc-cta-login { background: var(--canvas); color: var(--ink); }\n.own-vercel .vc-cta-login:hover { background: var(--canvas-soft-2); }\n.own-vercel .vc-cta-signup { background: var(--primary); color: var(--on-primary); }\n.own-vercel .vc-burger { display: none; place-items: center; width: 40px; height: 40px; border: 0; border-radius: var(--r-sm); background: var(--canvas); box-shadow: 0 0 0 1px var(--hairline); cursor: pointer; }\n.own-vercel .vc-burger svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }\n.own-vercel .vc-drawer { display: grid; gap: 2px; padding: 12px var(--gut) 16px; border-bottom: 1px solid var(--hairline); background: var(--canvas); }\n.own-vercel .vc-drawer a { font-size: 15px; font-weight: 500; padding: 10px 12px; border-radius: var(--r-md); }\n.own-vercel .vc-drawer a:hover { background: var(--canvas-soft-2); }\n\n/* ── mesh gradient ───────────────────────────────────────────────────── */\n.own-vercel .vc-hero { position: relative; overflow: hidden; padding-top: clamp(48px, 7cqi, 96px); }\n.own-vercel .vc-mesh { position: absolute; inset: -10% -5% auto; height: 640px; filter: blur(70px); opacity: .6; pointer-events: none; }\n.own-vercel .vc-blob { position: absolute; border-radius: 50%; }\n.own-vercel .vc-blob-a { width: 46%; height: 320px; left: 2%; top: 8%; background: radial-gradient(circle, #007cf0, #00dfd8 70%); }\n.own-vercel .vc-blob-b { width: 42%; height: 300px; left: 30%; top: 0; background: radial-gradient(circle, #7928ca, #ff0080 70%); }\n.own-vercel .vc-blob-c { width: 40%; height: 280px; right: 2%; top: 14%; background: radial-gradient(circle, #ff4d4d, #f9cb28 70%); }\n.own-vercel .vc-hero-in { position: relative; z-index: 2; text-align: center; max-width: 820px; }\n.own-vercel .vc-hero .vc-lead { max-width: 60ch; margin: 20px auto 28px; }\n.own-vercel .vc-hero-cta { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }\n.own-vercel .vc-hero-note { font-size: 14px; color: var(--mute); margin-top: 16px; }\n\n.own-vercel .vc-strip-wrap { position: relative; z-index: 2; max-width: 1400px; margin: clamp(40px, 6cqi, 72px) auto 0; padding: 0 var(--gut); }\n.own-vercel .vc-strip-cap { font-family: var(--f-mono); font-size: 12px; text-transform: uppercase; color: var(--mute); text-align: center; margin-bottom: 18px; }\n.own-vercel .vc-strip { display: flex; justify-content: center; align-items: center; gap: clamp(24px, 5cqi, 64px); flex-wrap: wrap; padding: 24px 0 clamp(40px, 6cqi, 72px); }\n.own-vercel .vc-strip span { font-size: 16px; font-weight: 600; letter-spacing: -.4px; color: var(--body); opacity: .8; }\n\n/* ── bands ───────────────────────────────────────────────────────────── */\n.own-vercel .vc-band { padding: var(--sec) 0; }\n.own-vercel .vc-band-soft { background: var(--canvas-soft); }\n.own-vercel .vc-band-mesh { position: relative; overflow: hidden; background: var(--canvas-soft); }\n.own-vercel .vc-band-mesh::before {\n  content: ''; position: absolute; top: -30%; left: 0; right: 0; height: 520px; filter: blur(80px); opacity: .35;\n  background: linear-gradient(90deg, #007cf0, #00dfd8 30%, #7928ca 55%, #ff0080 75%, #f9cb28 100%); pointer-events: none;\n}\n.own-vercel .vc-band-mesh .vc-wrap { position: relative; z-index: 2; }\n.own-vercel .vc-band-dark { background: var(--primary); color: var(--on-primary); }\n\n/* ── feature 3-up ────────────────────────────────────────────────────── */\n.own-vercel .vc-feature3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 36px; }\n.own-vercel .vc-feature {\n  background: var(--canvas); border-radius: var(--r-md); padding: 24px; box-shadow: var(--shadow-4);\n  display: flex; flex-direction: column; gap: 12px;\n}\n.own-vercel .vc-feature-icon { width: 40px; height: 40px; border-radius: var(--r-md); display: grid; place-items: center; background: var(--canvas-soft-2); }\n.own-vercel .vc-feature-icon svg { width: 22px; height: 22px; fill: none; stroke: var(--ink); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }\n.own-vercel .vc-feature h3 { font-size: 20px; font-weight: 600; letter-spacing: -.6px; }\n.own-vercel .vc-feature p { font-size: 14px; line-height: 1.5; letter-spacing: -.28px; color: var(--body); }\n.own-vercel .vc-feature .vc-link { margin-top: auto; }\n\n/* ── showcase / code editor ──────────────────────────────────────────── */\n.own-vercel .vc-show-in { display: grid; grid-template-columns: 1fr 1.1fr; gap: clamp(24px, 5cqi, 72px); align-items: center; }\n.own-vercel .vc-show-copy .vc-body { max-width: 46ch; margin: 18px 0 22px; }\n.own-vercel .vc-link { display: inline-flex; align-items: center; gap: 6px; font-size: 14px; font-weight: 500; color: var(--link); }\n.own-vercel .vc-link svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }\n.own-vercel .vc-editor { background: var(--primary); border-radius: var(--r-md); overflow: hidden; box-shadow: var(--shadow-5); }\n.own-vercel .vc-editor-top { display: flex; align-items: center; gap: 6px; padding: 12px 16px; border-bottom: 1px solid rgba(255,255,255,.1); }\n.own-vercel .vc-edot { width: 9px; height: 9px; border-radius: 50%; background: rgba(255,255,255,.24); }\n.own-vercel .vc-editor-file { margin-left: 10px; font-family: var(--f-mono); font-size: 12px; color: rgba(255,255,255,.55); }\n.own-vercel .vc-editor-body { margin: 0; padding: 20px; overflow-x: auto; font-family: var(--f-mono); font-size: 13px; line-height: 1.55; color: #f2f2f2; }\n.own-vercel .vc-editor-body code { font-family: inherit; }\n.own-vercel .vc-c-kw { color: #ff0080; }\n.own-vercel .vc-c-str { color: #50e3c2; }\n.own-vercel .vc-c-num { color: #f9cb28; }\n\n/* ── template grid ───────────────────────────────────────────────────── */\n.own-vercel .vc-tpl-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; }\n.own-vercel .vc-tpl {\n  background: var(--canvas); border-radius: var(--r-md); padding: 16px; box-shadow: var(--shadow-2);\n  display: flex; flex-direction: column; gap: 12px;\n}\n.own-vercel .vc-tpl-thumb { aspect-ratio: 16 / 9; border-radius: var(--r-sm); background: linear-gradient(140deg, var(--c, #007cf0), var(--c2, #00dfd8)); }\n.own-vercel .vc-tpl-name { font-size: 14px; font-weight: 500; letter-spacing: -.28px; }\n.own-vercel .vc-tpl-meta { font-family: var(--f-mono); font-size: 12px; color: var(--mute); }\n\n/* ── dark band stats ─────────────────────────────────────────────────── */\n.own-vercel .vc-dark-in { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(24px, 5cqi, 72px); align-items: center; }\n.own-vercel .vc-dark-copy .vc-body-on-dark { max-width: 46ch; margin-top: 18px; }\n.own-vercel .vc-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 2px; background: rgba(255,255,255,.12); border-radius: var(--r-md); overflow: hidden; }\n.own-vercel .vc-stat { background: var(--primary); padding: 28px 24px; }\n.own-vercel .vc-stat-num { font-size: clamp(30px, 3.4cqi, 40px); font-weight: 600; letter-spacing: -1.4px; line-height: 1; }\n.own-vercel .vc-stat-lab { font-family: var(--f-mono); font-size: 12px; color: rgba(255,255,255,.6); margin-top: 8px; }\n\n/* ── pricing ─────────────────────────────────────────────────────────── */\n.own-vercel .vc-pricing { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; align-items: start; }\n.own-vercel .vc-tier {\n  background: var(--canvas); border-radius: var(--r-lg); padding: 32px; box-shadow: var(--shadow-4);\n  display: flex; flex-direction: column; gap: 16px;\n}\n.own-vercel .vc-tier-featured { background: var(--primary); color: var(--on-primary); }\n.own-vercel .vc-tier-name { font-size: 24px; font-weight: 600; letter-spacing: -.96px; }\n.own-vercel .vc-tier-price { font-size: clamp(30px, 3.6cqi, 40px); font-weight: 600; letter-spacing: -1.4px; line-height: 1; }\n.own-vercel .vc-tier-price small { font-size: 15px; font-weight: 400; letter-spacing: 0; color: var(--mute); }\n.own-vercel .vc-tier-featured .vc-tier-price small { color: rgba(255,255,255,.7); }\n.own-vercel .vc-tier ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }\n.own-vercel .vc-tier li { display: flex; gap: 10px; font-size: 15px; line-height: 1.5; color: var(--body); }\n.own-vercel .vc-tier-featured li { color: rgba(255,255,255,.82); }\n.own-vercel .vc-tier li svg { width: 18px; height: 18px; flex: none; fill: none; stroke: var(--link); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; margin-top: 2px; }\n.own-vercel .vc-tier-featured li svg { stroke: #50e3c2; }\n.own-vercel .vc-tier .vc-btn { margin-top: auto; }\n.own-vercel .vc-tier-featured .vc-btn-primary { background: var(--canvas); color: var(--ink); }\n\n/* ── footer ──────────────────────────────────────────────────────────── */\n.own-vercel .vc-foot { background: var(--canvas); border-top: 1px solid var(--hairline); padding: 64px 0 48px; }\n.own-vercel .vc-foot-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }\n.own-vercel .vc-foot-grid > div { display: flex; flex-direction: column; gap: 10px; }\n.own-vercel .vc-foot-head { font-family: var(--f-mono); font-size: 12px; text-transform: uppercase; letter-spacing: .04em; color: var(--mute); margin-bottom: 4px; }\n.own-vercel .vc-foot-grid a { font-size: 14px; letter-spacing: -.28px; color: var(--body); }\n.own-vercel .vc-foot-grid a:hover { color: var(--ink); }\n.own-vercel .vc-foot-bottom {\n  display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\n  margin-top: 40px; padding-top: 24px; border-top: 1px solid var(--hairline); font-size: 12px; color: var(--mute);\n}\n.own-vercel .vc-foot-brand { display: inline-flex; align-items: center; gap: 8px; font-size: 15px; font-weight: 600; letter-spacing: -.4px; color: var(--ink); }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-vercel .vc-nav-links { display: none; }\n  .own-vercel .vc-burger { display: grid; }\n  .own-vercel .vc-tpl-grid { grid-template-columns: repeat(3, 1fr); }\n  .own-vercel .vc-feature3 { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 760px) {\n  .own-vercel .vc-feature3 { grid-template-columns: 1fr; }\n  .own-vercel .vc-show-in, .own-vercel .vc-dark-in { grid-template-columns: 1fr; }\n  .own-vercel .vc-pricing { grid-template-columns: 1fr; }\n  .own-vercel .vc-tpl-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-vercel .vc-foot-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-vercel .vc-nav-actions .vc-cta-login { display: none; }\n}\n@container frame (max-width: 430px) {\n  .own-vercel .vc-hero-cta { flex-direction: column; }\n  .own-vercel .vc-hero-cta .vc-btn { width: 100%; }\n  .own-vercel .vc-tpl-grid { grid-template-columns: 1fr; }\n  .own-vercel .vc-stats { grid-template-columns: 1fr; }\n  .own-vercel .vc-foot-grid { grid-template-columns: 1fr; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-vercel *, .own-vercel *::before, .own-vercel *::after {\n    animation-duration: .001ms !important; transition-duration: .001ms !important;\n  }\n}\n"};
/* ══ VERCEL — Northwind operations analytics ════════════════════════════════════
   Registers window.OWN_LAYOUTS['vercel'].init(root). Renders the 3-up feature row,
   template grid, dark-band stats and pricing tiers from sample data; wires the
   mobile drawer. Returns a cleanup that removes every listener. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  var ICONS = {
    deploy: 'M12 3v12M7 8l5-5 5 5M5 21h14',
    chart: 'M4 19V9M10 19V5M16 19v-7M3 19h18',
    shield: 'M12 3l8 3v6c0 5-4 8-8 9-4-1-8-4-8-9V6zM9 12l2 2 4-4'
  };

  var FEATURES = [
    { icon: 'deploy', title: 'Deploy in seconds', body: 'Push a metric from your pipeline and Northwind renders a live board before the next standup.', link: 'Start deploying' },
    { icon: 'chart', title: 'Scale to any region', body: 'One ledger for six regions today, sixty tomorrow. Capacity scales with your operations, not your headcount.', link: 'See the platform' },
    { icon: 'shield', title: 'Secure by default', body: 'SOC 2 Type II, per-region data residency, and an audit log on every query. Compliance out of the box.', link: 'Read the trust page' }
  ];

  var TEMPLATES = [
    { name: 'Throughput board', meta: 'ops', c: '#007cf0', c2: '#00dfd8' },
    { name: 'Revenue pulse', meta: 'finance', c: '#7928ca', c2: '#ff0080' },
    { name: 'Region compare', meta: 'ops', c: '#ff4d4d', c2: '#f9cb28' },
    { name: 'Support health', meta: 'service', c: '#00dfd8', c2: '#007cf0' },
    { name: 'Capacity plan', meta: 'teams', c: '#ff0080', c2: '#7928ca' }
  ];

  var STATS = [
    { num: '99.99%', lab: 'Platform uptime' },
    { num: '40 ms', lab: 'Median query' },
    { num: '6', lab: 'Regions live' },
    { num: '12B', lab: 'Events / month' }
  ];

  var TIERS = [
    { name: 'Hobby', price: '$0', per: '/mo', feats: ['1 region', '10 dashboards', 'Community support'], cta: 'Start free', featured: false },
    { name: 'Pro', price: '$20', per: '/seat / mo', feats: ['Unlimited regions', 'Alerts & workflows', 'Priority support'], cta: 'Start free', featured: true },
    { name: 'Enterprise', price: 'Custom', per: '', feats: ['SSO & audit log', 'Data residency', 'Dedicated engineer'], cta: 'Talk to sales', featured: false }
  ];

  OWN['vercel'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var $ = function (s) { return root.querySelector(s); };
      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }

      var f3 = $('#vcFeature3');
      if (f3) {
        f3.innerHTML = FEATURES.map(function (f) {
          return '<article class="vc-feature">'
            + '<span class="vc-feature-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="' + esc(ICONS[f.icon]) + '"/></svg></span>'
            + '<h3>' + esc(f.title) + '</h3>'
            + '<p>' + esc(f.body) + '</p>'
            + '<a class="vc-link" href="#">' + esc(f.link) + ' <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></a></article>';
        }).join('');
      }

      var tpl = $('#vcTplGrid');
      if (tpl) {
        tpl.innerHTML = TEMPLATES.map(function (t) {
          return '<a class="vc-tpl" href="#">'
            + '<span class="vc-tpl-thumb" style="--c:' + esc(t.c) + ';--c2:' + esc(t.c2) + '" aria-hidden="true"></span>'
            + '<span class="vc-tpl-name">' + esc(t.name) + '</span>'
            + '<span class="vc-tpl-meta">' + esc(t.meta) + '</span></a>';
        }).join('');
      }

      var stats = $('#vcStats');
      if (stats) {
        stats.innerHTML = STATS.map(function (s) {
          return '<div class="vc-stat"><span class="vc-stat-num">' + esc(s.num) + '</span>'
            + '<span class="vc-stat-lab">' + esc(s.lab) + '</span></div>';
        }).join('');
      }

      var pricing = $('#vcPricingGrid');
      if (pricing) {
        pricing.innerHTML = TIERS.map(function (t) {
          return '<div class="vc-tier' + (t.featured ? ' vc-tier-featured' : '') + '">'
            + '<span class="vc-tier-name">' + esc(t.name) + '</span>'
            + '<span class="vc-tier-price">' + esc(t.price) + ' <small>' + esc(t.per) + '</small></span>'
            + '<ul>' + t.feats.map(function (f) {
              return '<li><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12l4 4 10-10"/></svg>' + esc(f) + '</li>';
            }).join('') + '</ul>'
            + '<a class="vc-btn vc-btn-primary" href="#">' + esc(t.cta) + '</a></div>';
        }).join('');
      }

      var burger = $('[data-vc-menu]');
      var drawer = $('[data-vc-drawer]');
      on(burger, 'click', function () {
        if (!drawer) return;
        var open = drawer.hidden;
        drawer.hidden = !open;
        burger.setAttribute('aria-expanded', String(open));
      });

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) {} }
      };
    }
  };
})();
